# finite_form: Let $m=11449=107^2$ (with $107\equiv 3\pmod 8$, the type of digit modulus used in the explicit construction). Find a set $A\subseteq\{0,1,\dots,11448\}$ such that for every residue $x$ modulo $11449$ the number $r_A(x)$ of unordered pairs $\{a,a'\}$ with $a,a'\in A$ ($a=a'$ allowed) and $a+a'\equiv 
# candidate_format: A JSON array of distinct integers, each between 0 and 11448 inclusive, listing the elements of A (order irrelevant, length at most 400).

def check(candidate) -> bool:
    try:
        m = 11449
        T = 4
        if not isinstance(candidate, list):
            return False
        if len(candidate) == 0 or len(candidate) > 400:
            return False
        A = []
        for v in candidate:
            if isinstance(v, bool) or not isinstance(v, int):
                return False
            if v < 0 or v >= m:
                return False
            A.append(v)
        if len(set(A)) != len(A):
            return False
        k = len(A)
        # pigeonhole: k(k+1)/2 unordered pairs must fit in m residues with at most T each
        if k * (k + 1) // 2 > T * m:
            return False
        cnt = [0] * m
        for i in range(k):
            ai = A[i]
            for j in range(i, k):
                s = (ai + A[j]) % m
                cnt[s] += 1
                if cnt[s] > T:
                    return False
        for c in cnt:
            if c < 1:
                return False
        return True
    except Exception:
        return False
